# Define function spaces for displacement and pressure (mixed formulation for incompressibility)
# For Mooney-Rivlin with near incompressibility, we use a mixed u-p formulation.
# We'll use Taylor-Hood elements: P2 for displacement, P1 for pressure.
W = MixedFunctionSpace([V, Q])

# Define trial and test functions
du = TrialFunction(W)
v = TestFunction(W)
w = Function(W)
u, p = split(w)

# Kinematics
I = Identity(2)
F = I + grad(u)  # Deformation gradient
C = F.T * F
J = det(F)

# Mooney-Rivlin strain energy density
# W = C10*(I1 - 3) + C01*(I2 - 3) + K/2*(J-1)^2
# where I1 = J^{-2/3} * tr(C), I2 = J^{-4/3} * (tr(C)^2 - tr(C^2))/2
I1 = J**(-2.0/3.0) * tr(C)
I2 = J**(-4.0/3.0) * 0.5 * (tr(C)**2 - tr(C*C))
psi = C10 * (I1 - 3) + C01 * (I2 - 3) + K/2 * (J - 1)**2

